-- Extracted unique SQL queries from sql_log_query.sql
-- Total found: 97, Unique: 6

-- Query 1
SELECT    COUNT(LGM_STOCKBASELISTV.ID),       CASE     WHEN COUNT(LGM_STOCKBASELISTV.ID) = 0 THEN null     ELSE '@@@N@@@hook'    END FROM  LGM_STOCKBASELISTV  WHERE  LGM_STOCKBASELISTV.COSTUNIT  = '@@@N@@@1703169000'  AND LGM_STOCKBASELISTV.WORKPLACE  = '@@@N@@@B12 ZENTRALLAGER'  AND LGM_STOCKBASELISTV.BOOKSTATENR  in ( 1  , - 1  )

-- Query 2
SELECT    LGM_STOCKBASELISTV.BOOKSTATENR,    LGM_STOCKBASELISTV.IDTYPE,    LGM_STOCKBASELISTV.ID,    LGM_STOCKBASELISTV.STOCKTYPEID,    ABS(LGM_STOCKBASELISTV.COUNTNEW),    ABS(LGM_STOCKBASELISTV.COUNTUSED),    ABS(LGM_STOCKBASELISTV.COUNTREPAIR),    LGM_STOCKBASELISTV.STOCKPLACEID,    ISNULL(TMS_COSTUNITSTOCKPLACE.NAME00, TMS_COSTUNITSTOCKPLACE.NAME) COSTUNITSTOCKPLACENAME,    TMS_COSTUNITSTOCKPLACE.HALL,    TMS_COSTUNITSTOCKPLACE.SHELF,    TMS_COSTUNITSTOCKPLACE.DRAWER,    TMS_COSTUNITSTOCKPLACE.GRID,    TMS_COSTUNITSTOCKPLACE.WIDTH,    TMS_COSTUNITSTOCKPLACE.DEPTH,    TMS_COSTUNITSTOCKPLACE.HEIGHT,    TMS_COSTUNITSTOCKPLACE.DEVICETYPE,    TMS_COSTUNITSTOCKPLACE.DEVICEID,    LGM_STOCKBASELISTV.COSTUNIT,    LGM_STOCKBASELISTV.WORKPLACE,    LGM_STOCKBASELISTV.ACCOUNTID,    CONVERT(VARCHAR(23), LGM_STOCKBASELISTV.CANCELNR),    LGM_STOCKBASELISTV.INVID,    LGM_HISTORYBASE.BOOKTIMESTAMP,    LGM_STOCKBASELISTV.[TIMESTAMP],    DBO.Tms_Idv_F_Getname(LGM_STOCKBASELISTV.IDTYPE, LGM_STOCKBASELISTV.ID, '@@@N@@@00') NAME,    DBO.Tms_Idv_F_Getname2(LGM_STOCKBASELISTV.IDTYPE, LGM_STOCKBASELISTV.ID, '@@@N@@@00') NAME2,    LGM_HISTORYBASE.COSTUNITTO,    LGM_HISTORYBASE.WORKPLACETO,    LGM_HISTORYBASE.USERID,    LGM_HISTORYBASE.LISTID,    LGM_HISTORYBASE.AREA,    LGM_HISTORYBASE.BOOKTYPE,    TMS_DEVICE.MOD FROM  LGM_STOCKBASELISTV  LEFT OUTER JOIN  TMS_COSTUNITSTOCKPLACE  ON  LGM_STOCKBASELISTV.STOCKPLACEID  = TMS_COSTUNITSTOCKPLACE.STOCKPLACEID   AND LGM_STOCKBASELISTV.COSTUNIT  = TMS_COSTUNITSTOCKPLACE.COSTUNIT   AND LGM_STOCKBASELISTV.WORKPLACE  = TMS_COSTUNITSTOCKPLACE.WORKPLACE   LEFT OUTER JOIN  TMS_DEVICE  ON  TMS_COSTUNITSTOCKPLACE.DEVICEID  = TMS_DEVICE.DEVICEID ,   LGM_HISTORYBASE,   TMS_IDV  WHERE  LGM_HISTORYBASE.IDTYPE  = TMS_IDV.IDTYPE  AND LGM_HISTORYBASE.ID  = TMS_IDV.ID  AND LGM_STOCKBASELISTV.ID  = TMS_IDV.ID  AND LGM_STOCKBASELISTV.IDTYPE  = TMS_IDV.IDTYPE  AND (LGM_STOCKBASELISTV.BOOKSTATENR  = - 1  OR LGM_STOCKBASELISTV.BOOKSTATENR  = 1)  AND LGM_STOCKBASELISTV.COSTUNIT  = '@@@N@@@1703169000'  AND LGM_STOCKBASELISTV.WORKPLACE  = '@@@N@@@B12 ZENTRALLAGER'  AND LGM_HISTORYBASE.CANCELNR  = LGM_STOCKBASELISTV.CANCELNR ORDER BY TMS_COSTUNITSTOCKPLACE.HALL,   TMS_COSTUNITSTOCKPLACE.SHELF,   TMS_COSTUNITSTOCKPLACE.DRAWER,   TMS_COSTUNITSTOCKPLACE.GRID,   TMS_COSTUNITSTOCKPLACE.WIDTH,   TMS_COSTUNITSTOCKPLACE.DEPTH,   TMS_COSTUNITSTOCKPLACE.HEIGHT

-- Query 3
SELECT    MAX(SYS_LOGGING.ACTION) MAXACTION,    SYS_LOGGING.ACTIONTIMESTAMP FROM  SYS_LOGGING  WHERE  USERID  = '@@@N@@@SAD'  AND LOGGINGID  = '@@@N@@@1770723082' GROUP BY  SYS_LOGGING.ACTIONTIMESTAMP

-- Query 4
SELECT MAX(TRAFFICLIGHTSTATE) TRAFFICLIGHTSTATE FROM  TMS_SYSEVALUATION INNER JOIN TMS_USERSYSEVALUATION ON TMS_SYSEVALUATION.SYSEVALUATIONID  = TMS_USERSYSEVALUATION.SYSEVALUATIONID   WHERE  TMS_USERSYSEVALUATION.USERID  = '@@@N@@@SAD'

